import 'package:flutter/material.dart';
import '../services/api.dart';
class DriversScreen extends StatefulWidget{const DriversScreen({super.key});@override State<DriversScreen> createState()=>_DriversScreenState();}
class _DriversScreenState extends State<DriversScreen>{bool loading=true;String? error;List<dynamic> drivers=[];
@override void initState(){super.initState();load();}Future<void> load()async{try{drivers=await Api.instance.drivers();error=null;}catch(e){error=e.toString();}if(mounted)setState(()=>loading=false);}
@override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());if(error!=null)return Center(child:Text(error!));return ListView.separated(padding:const EdgeInsets.all(12),itemCount:drivers.length,separatorBuilder:(_,__)=>const SizedBox(height:5),itemBuilder:(_,i){final d=Map<String,dynamic>.from(drivers[i]);return Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(d['name']?.toString()??'?'),subtitle:Text('المركبة الحالية: '+(d['vehicle']?.toString()??'غير محددة')),onTap:()async{final h=await Api.instance.driverHistory(d['user_id'].toString());if(mounted)showModalBottomSheet(context:context,builder:(_)=>_History(data:h));}));});}}
class _History extends StatelessWidget{final Map<String,dynamic> data;const _History({required this.data});@override Widget build(BuildContext c){final d=Map<String,dynamic>.from(data['driver']??{});final h=List<dynamic>.from(data['assignment_history']??[]);final p=List<dynamic>.from(data['problems']??[]);return Directionality(textDirection:TextDirection.rtl,child:Padding(padding:const EdgeInsets.all(20),child:ListView(shrinkWrap:true,children:[Text(d['name']?.toString()??'-',style:const TextStyle(fontSize:22,fontWeight:FontWeight.w800)),Text('المركبة الحالية: '+(d['vehicle']?.toString()??'-')),const Divider(),const Text('تاريخ المركبات',style:TextStyle(fontWeight:FontWeight.bold)),...h.map((x)=>ListTile(dense:true,title:Text(x['vehicle'].toString()),subtitle:Text(x['assigned_from'].toString()+' → '+(x['assigned_until']??'حالياً').toString()))),const Divider(),const Text('الشكاوى والحوادث',style:TextStyle(fontWeight:FontWeight.bold)),...p.map((x)=>ListTile(dense:true,title:Text(x['problem_text'].toString()),subtitle:Text(x['date'].toString())))])));}}
